import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷四·6","description":"易小帖 - 卷四·6","frontmatter":{"title":"卷四·6","description":"易小帖 - 卷四·6"},"headers":[],"relativePath":"classics/yixiaotie/100.md","filePath":"classics/yixiaotie/100.md"}'),o={name:"classics/yixiaotie/100.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷四·6",tabindex:"-1"},[r("卷四·6 "),e("a",{class:"header-anchor",href:"#卷四·6","aria-label":"Permalink to “卷四·6”"},"​")],-1),e("p",null,"履虎尾彖曰「柔履剛也」。夫柔履剛則虎尾宜在六三之下，故蘇氏以九二為虎，六三履之。然於九四之履虎尾不通，乃又曰六三亦虎尾，九四履之，則是剛履柔矣。唐氏作《易義》，直謂乾健如虎，兌履其尾，謂履剛不是乘剛，是躡其後者。乘以上下言，躡以前後言。然於九四之履虎尾，終不得通。因曲為之說曰：三之履尾是履彼尾也，四之履尾是我有尾而為人所履也。則周章甚矣。殊不知，乾兌皆虎，乾兌皆尾，乾兌皆履。其雲柔履剛者，雖單指六三一爻，而實則履上履下。或踐或躡，統皆有之，蓋乾兌皆金，皆位西方，而虎為西方金獸，禮所雲右白虎者，則彼踐此躡，剛柔皆見而世不解也。若虞仲翔謂坤為虎，艮為尾，震為履，以履與謙變對，謙上坤下艮，因以為象，則坤為虎，在《九家易》雖有之，而以謙釋履，舍烏而說鵠，無是理矣。至《程傳》，一概抹煞，但曰雖履虎尾亦得此。與朱氏解需彖雖涉大川猶可同一妙語。夫大聖措詞必無汎設，若然，則鶴鳴鴻漸，豶豖童牛，皆洵口漫道，可雲演易乎。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
